// Original QuickReply payload lives on the webhook node. Guard so testing a
// single node in isolation doesn't hard-crash.
let body = {};
try {
  body = $('QuickReply Webhook').first().json.body || {};
} catch (e) {
  const inp = $input.first();
  body = (inp && inp.json && (inp.json.body || inp.json)) || {};
}

const phone = body.phone || '';
const name = body.name || 'Customer';
const msgId = body.id || '';
const msgTime = Number(body.msg_time) || Date.now();
const payload = body.payload || {};
const text = payload.text || '';

// ---- Classify the message (confirmed from prod cloud-run logs) ----
//  text        -> _type USER_TEXT, has payload.text
//  image       -> _type USER_FILE, contentType image/jpeg
//  audio/voice -> _type USER_FILE, contentType audio/ogg, audioText ""
//  button tap  -> _type USER_LIST_REPLY / USER_BUTTON_REPLY
const ptype = String(payload._type || '').toUpperCase();
const contentType = String(payload.contentType || '').toLowerCase();
const hasText = !!(text && String(text).trim());

// MEDIA = any uploaded file: image, audio voice-note, report, document.
const isMedia = ptype === 'USER_FILE'
  || (!hasText && ptype && ptype !== 'USER_TEXT')
  || (!hasText && (contentType.startsWith('image/') || contentType.startsWith('audio/')));
let mediaKind = 'text';
if (isMedia) {
  if (contentType.startsWith('image/')) mediaKind = 'image';
  else if (contentType.startsWith('audio/')) mediaKind = 'audio';
  else mediaKind = 'file';
}
const mediaPath = payload.path || '';

// AUTOMATION / TEMPLATE triggers the AI must NOT answer — QuickReply's own flows
// already handle these (e.g. the Health Score CTA sends its link automatically).
// Add new predefined-button texts to AUTOMATION_TRIGGERS (matched case-insensitive).
const AUTOMATION_TRIGGERS = [
  'check my free health score',
  'check free healthscore',
  'i want my detailed healthscore',
  'mujhe vaji bati or kern drops chahiye'
];
const textLc = String(text || '').toLowerCase().trim();
const isTriggerText = AUTOMATION_TRIGGERS.some(t => textLc.includes(t));
const isButtonReply = ptype === 'USER_LIST_REPLY' || ptype === 'USER_BUTTON_REPLY';
const isAutomation = isTriggerText || isButtonReply;

// The AI answers ONLY real typed questions. Skip media + automation/button messages.
const skipAi = isMedia || isAutomation;
let skipReason = '';
if (isMedia) skipReason = 'media_' + mediaKind;
else if (isButtonReply) skipReason = 'button_reply';
else if (isTriggerText) skipReason = 'automation_trigger';

return [{
  json: {
    phone,
    name,
    msgId,
    msgTime,
    text,
    msgType: ptype,
    isMedia,
    mediaKind,
    mediaPath,
    isAutomation,
    skipAi,
    skipReason,
    convId: phone.replace(/[^0-9]/g, ''),   // matches CF qrConvId()
    savedAt: new Date().toISOString()
  }
}];

const RESUME_AFTER_SILENCE_MS = 30 * 60 * 1000; // human-silence before AI resumes

// This message's own trigger time (from the webhook). No static data - the whole
// decision is derived from the durable Firestore messages, so it works the same in
// test and production executions.
const src = $('Extract Message Details').first().json;
const phone = src.phone;
const name = src.name || 'Customer';
const myMsgTime = Number(src.msgTime) || 0;

// ---- per-number lists (global 'off' already short-circuited by "AI Enabled?") ----
let mode = 'on';
let testNumbers = ['+917300978845', '+918756112227'];
let blockedNumbers = [];
const toList = (v) => {
  if (!v) return [];
  const raw = Array.isArray(v) ? v.join(',') : String(v);
  return raw.split(',').map(s => s.trim()).filter(Boolean);
};
try {
  const cfg = $('Get AI Config').first().json;
  if (cfg && typeof cfg.mode === 'string' && cfg.mode.trim()) mode = cfg.mode.trim().toLowerCase();
  const tn = toList(cfg && cfg.testNumbers);
  if (tn.length) testNumbers = tn;
  blockedNumbers = toList(cfg && cfg.blockedNumbers);
} catch (e) {}

if (blockedNumbers.includes(phone)) return [{ json: { phone, name, shouldProcess: false, reason: 'ai_blocked_number' } }];
if (mode === 'off') return [{ json: { phone, name, shouldProcess: false, reason: 'ai_paused_global' } }];
if (mode === 'test' && !testNumbers.includes(phone)) return [{ json: { phone, name, shouldProcess: false, reason: 'ai_test_mode_only' } }];

// ---- read messages from conversations/{convId}/messages ----
//   customer      = direction 'in'
//   AI reply      = out + senderKind 'AI'     (Save AI Message; legacy: messageBy 'AI')
//   human reply   = out + senderKind 'HUMAN'  (CRM composer / qrSendMessage) - HAS text
//                   OR an AGENT_PLACEHOLDER   (QuickReply dashboard)         - no text
let items = [];
try { items = $('Fetch Conversation History').all(); } catch (e) { items = []; }
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();

// The AI sends via ONE fixed QuickReply agent account; a dashboard takeover comes from
// a DIFFERENT account, told apart by agentId.
const AI_AGENT_IDS = new Set(['u9ocdFtszn6BAXa7L_ag']);  // <- AI's own QuickReply send account(s)

// senderKind is stamped at write time and is never touched by the status callbacks, so
// it survives; messageBy and agentId are both overwritten in place by QuickReply's
// SENT/DELIVERED/READ callbacks and cannot be trusted on their own.
const isAiOut = m => m.senderKind === 'AI' || m.messageBy === 'AI';
const isHumanOut = m => !isAiOut(m) && (
     m.senderKind === 'HUMAN'
  || (m._type === 'AGENT_PLACEHOLDER' && !m.automationBy && !AI_AGENT_IDS.has(String(m.agentId || '')))
);

// Pass 1 - learn extra AI send accounts, but ONLY from messages explicitly marked as the
// AI's own. The old code learned from "any outbound message that has text", so a human
// agent's CRM reply (AGENT_TEXT + text) both counted as an AI reply AND registered that
// agent as an AI account - after which the bot never paused for them again.
for (const it of items) {
  const m = it && it.json; if (!m) continue;
  if (m.direction === 'out' && m.agentId && isAiOut(m)) AI_AGENT_IDS.add(String(m.agentId));
}

let latestInboundAt = 0, lastAiAt = 0, lastHumanAt = 0;
const inbound = [];
for (const it of items) {
  const m = it && it.json; if (!m) continue;
  const t = tval(m);
  if (m.direction === 'in') {
    latestInboundAt = Math.max(latestInboundAt, t);
    if (m.text) inbound.push({ t, text: String(m.text) });
    continue;
  }
  if (m.direction !== 'out') continue;
  if (isHumanOut(m)) { lastHumanAt = Math.max(lastHumanAt, t); continue; }
  if (isAiOut(m)) { lastAiAt = Math.max(lastAiAt, t); continue; }
  // Legacy / ambiguous outbound text, written before senderKind existed. Count it as the
  // AI: calling it "human" would read every historical AI reply as a takeover and
  // silence the bot on every chat it has ever answered.
  if (m.text && !m.placeholder && m._type !== 'BOT_PLACEHOLDER') lastAiAt = Math.max(lastAiAt, t);
}

console.log('[Decide Process] fetched=' + items.length
  + ' lastInbound=' + (latestInboundAt ? new Date(latestInboundAt).toISOString() : '-')
  + ' lastAi=' + (lastAiAt ? new Date(lastAiAt).toISOString() : '-')
  + ' lastHuman=' + (lastHumanAt ? new Date(lastHumanAt).toISOString() : '-'));

// ---- DEBOUNCE (Firestore-based): if a newer customer message arrived during the
//      wait, let THAT execution answer the whole batch - this one bows out. ----
if (latestInboundAt > myMsgTime) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'newer_message_wins', myMsgTime, latestInboundAt } }];
}

// ---- HANDOFF: a human agent is actively handling this chat ----
// Once a human agent has sent ANYTHING in the last RESUME window, the AI backs off -
// even if an in-flight AI reply happened to land after the human's message. The AI
// resumes only after the human has been quiet for the whole window.
const now = Date.now();
const humanActive = lastHumanAt > 0 && (now - lastHumanAt) < RESUME_AFTER_SILENCE_MS;
if (humanActive) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'human_active', minsSinceHuman: Math.round((now - lastHumanAt) / 60000), lastHumanAt } }];
}

// ---- already answered? ANY reply (AI text or a genuine human reply) newer than the
//      latest customer message => this / a duplicate execution bows out. ----
// NOT a QuickReply automation/bot template - those don't answer the query.
const answeredAt = Math.max(lastAiAt, lastHumanAt);
if (latestInboundAt > 0 && latestInboundAt <= answeredAt) {
  return [{ json: { phone, name, shouldProcess: false, reason: 'already_answered', lastAiAt, lastHumanAt } }];
}

// ---- text of the current turn, for the product lookup ----
// "Fetch Product Matches" runs before "Build AI Prompt", so it cannot use that node's
// newMsgText. It must not use only the triggering message either: a customer who types
// "vaji bati" and then "price?" would have the product name in the PREVIOUS message and
// match nothing. This is the same unanswered-messages set Build AI Prompt assembles.
let recentUserText = inbound.filter(m => m.t > answeredAt).map(m => m.text).join(' ');
if (!recentUserText && inbound.length) recentUserText = inbound[inbound.length - 1].text;
if (!recentUserText) recentUserText = String(src.text || '');
recentUserText = recentUserText.replace(/\s+/g, ' ').trim().slice(0, 300);

return [{ json: { phone, name, shouldProcess: true, reason: 'process', lastAiAt, lastHumanAt, recentUserText, resumedFromHuman: (lastHumanAt > 0 && lastHumanAt >= lastAiAt) } }];

const decide = $('Decide Process').first().json;
const phone = decide.phone;
const name = decide.name || 'Customer';

let items = [];
try { items = $('Fetch Conversation History').all(); } catch (e) { items = []; }
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();
const evs = items.map(i => i.json).filter(m => m && (m.msgTime || m.createdAt))
  .map(m => ({ ...m, _t: tval(m) })).sort((a, b) => a._t - b._t);

// Same classification as "Decide Process" - keep the two in sync. senderKind is stamped
// at write time and survives; messageBy and agentId are overwritten in place by
// QuickReply's status callbacks, so neither can be trusted on its own. A CRM-composer
// reply from a human agent is an AGENT_TEXT WITH text, which is exactly what an AI reply
// looks like - only senderKind tells them apart.
const AI_AGENT_IDS = new Set(['u9ocdFtszn6BAXa7L_ag']);
const isAiOut = m => m.senderKind === 'AI' || m.messageBy === 'AI';
const isHumanOut = m => !isAiOut(m) && (
     m.senderKind === 'HUMAN'
  || (m._type === 'AGENT_PLACEHOLDER' && !m.automationBy && !AI_AGENT_IDS.has(String(m.agentId || '')))
);
for (const m of evs) { if (m.direction === 'out' && m.agentId && isAiOut(m)) AI_AGENT_IDS.add(String(m.agentId)); }

const isHumanMsg = m => m.direction === 'out' && isHumanOut(m);
// legacy/ambiguous outbound text counts as the AI (see Decide Process for why)
const isAiMsg = m => m.direction === 'out' && !isHumanOut(m)
  && (isAiOut(m) || (!!m.text && !m.placeholder && m._type !== 'BOT_PLACEHOLDER'));

let lastAiAt = 0, lastHumanAt = 0, humanTextSeen = false;
for (const m of evs) {
  if (isHumanMsg(m)) { lastHumanAt = Math.max(lastHumanAt, m._t); if (m.text) humanTextSeen = true; }
  else if (isAiMsg(m)) lastAiAt = Math.max(lastAiAt, m._t);
}
const cutoff = Math.max(lastAiAt, lastHumanAt);
const resumedFromHuman = lastHumanAt > 0 && lastHumanAt >= lastAiAt;

// current turn = inbound user messages not yet answered
const unanswered = evs.filter(m => m.direction === 'in' && m._t > cutoff);
let newMsgText = unanswered.map(m => m.text || '').filter(Boolean).join('\n');
// Fallbacks so Gemini never receives an empty user message:
if (!newMsgText) {
  const lastUser = [...evs].reverse().find(m => m.direction === 'in' && m.text);
  if (lastUser) newMsgText = lastUser.text || '';
}
if (!newMsgText) {
  try { newMsgText = ($('Extract Message Details').first().json.text || '').trim(); } catch (e) {}
}

// transcript for context. A human agent's CRM reply HAS text, so feed it in as an
// assistant turn - the model then continues from what the human actually said instead of
// guessing. A QuickReply-dashboard takeover is text-less; those turns are invisible here
// and are flagged via the HANDOFF NOTE below.
const history = [];
for (const m of evs) {
  if (m.direction === 'in') { if (m._t > cutoff) continue; history.push({ role: 'user', content: m.text || '' }); }
  else if (isHumanMsg(m)) { if (m.text) history.push({ role: 'assistant', content: m.text }); }
  else if (isAiMsg(m)) history.push({ role: 'assistant', content: m.text || '' });
}
const recentHistory = history.slice(-20);

const isFirstContact = !history.some(h => h.role === 'assistant');

// ---- TIME AWARENESS: use the customer's OWN message time (msg_time), not Date.now() ----
let curMsgTime = 0;
if (unanswered.length) curMsgTime = unanswered[unanswered.length - 1]._t;
if (!curMsgTime) { const lu = [...evs].reverse().find(m => m.direction === 'in'); if (lu) curMsgTime = lu._t; }
if (!curMsgTime) { try { curMsgTime = Number($('Extract Message Details').first().json.msgTime) || 0; } catch (e) {} }
if (!curMsgTime) curMsgTime = Date.now();

const istNow = new Date(curMsgTime + (5.5 * 60 * 60 * 1000));
const H = istNow.getUTCHours();
const Min = istNow.getUTCMinutes();
const clock = (((H + 11) % 12) + 1) + ':' + String(Min).padStart(2, '0') + ' ' + (H < 12 ? 'AM' : 'PM') + ' IST';
let partOfDay = 'night';
if (H >= 5 && H < 12) partOfDay = 'morning';
else if (H >= 12 && H < 17) partOfDay = 'afternoon';
else if (H >= 17 && H < 21) partOfDay = 'evening';
const totalMinutes = H * 60 + Min;
const isOfficeHours = totalMinutes >= (9 * 60 + 30) && totalMinutes < (18 * 60 + 30);

// gap since the customer's PREVIOUS inbound message (how long they were away)
const firstUnansweredAt = unanswered.length ? unanswered[0]._t : curMsgTime;
let prevInboundAt = 0;
for (const m of evs) { if (m.direction === 'in' && m._t < firstUnansweredAt) prevInboundAt = Math.max(prevInboundAt, m._t); }
const gapMs = prevInboundAt ? (firstUnansweredAt - prevInboundAt) : 0;
function fmtGap(ms) {
  if (!ms) return 'first message / no prior';
  const min = Math.round(ms / 60000);
  if (min < 1) return 'just now';
  if (min < 60) return min + ' min ago';
  const hr = Math.round(min / 60);
  if (hr < 24) return hr + ' hr ago';
  const d = Math.round(hr / 24);
  return d + ' day' + (d > 1 ? 's' : '') + ' ago';
}
const gapLabel = fmtGap(gapMs);

let basePrompt = 'You are Ananya, a Health Expert at SehatUP.';
try {
  const docData = $('Get a document').first().json;
  if (docData && docData.body && docData.body.content && Array.isArray(docData.body.content)) {
    const extracted = docData.body.content
      .map(b => b.paragraph && b.paragraph.elements
        ? b.paragraph.elements.map(e => (e.textRun && e.textRun.content) ? e.textRun.content : '').join('')
        : '')
      .join('').trim();
    if (extracted) basePrompt = extracted;
  }
} catch (e) { console.log('Could not read Google Doc, using default prompt:', e.message); }

// ---- GOOGLE DOC INTEGRITY ----
// The Doc has come back truncated more than once, and it fails SILENTLY: the prompt still
// reads plausibly, it has just lost clauses - including safety rules. The damage is a
// fixed-width artifact (chunks of exactly 29-30 characters missing at intervals), which is
// what you get when the text is copied out of a panel that renders it with part of each
// line scrolled out of view, then pasted back into the Doc. Copy from ananya-prompt.txt in
// a plain text editor, never from a rendered panel.
// This check cannot repair it, but it makes it loud instead of invisible.
const DOC_MIN_CHARS = 15000;                        // ananya-prompt.txt is ~17.9k
const DOC_REQUIRED = ['RULES:', 'DOSAGE', 'ORDERS, DELIVERY & PAYMENT', 'LIVE PRODUCT DATA & PRICES', 'CATALOG', 'FIRST-MESSAGE TEMPLATE', 'EXAMPLES'];
const docChars = basePrompt.length;
const docMissing = DOC_REQUIRED.filter(k => basePrompt.indexOf(k) < 0);
const docOk = docChars >= DOC_MIN_CHARS && docMissing.length === 0;
if (!docOk) {
  console.log('[Build AI Prompt] !! GOOGLE DOC LOOKS DAMAGED: ' + docChars + ' chars (expected >= '
    + DOC_MIN_CHARS + ')' + (docMissing.length ? ' | MISSING SECTIONS: ' + docMissing.join(' / ') : '')
    + ' -- re-paste from ananya-prompt.txt using a plain text editor, not a rendered panel.');
}

// ---- LANGUAGE: detect the script the customer typed in. We still answer only in
//      Hindi / English / Hinglish, but the model is told what it is reading. ----
const SCRIPTS = [
  { name: 'Hindi (Devanagari)', re: /[\u0900-\u097F]/ },
  { name: 'Bengali', re: /[\u0980-\u09FF]/ },
  { name: 'Punjabi (Gurmukhi)', re: /[\u0A00-\u0A7F]/ },
  { name: 'Gujarati', re: /[\u0A80-\u0AFF]/ },
  { name: 'Odia', re: /[\u0B00-\u0B7F]/ },
  { name: 'Tamil', re: /[\u0B80-\u0BFF]/ },
  { name: 'Telugu', re: /[\u0C00-\u0C7F]/ },
  { name: 'Kannada', re: /[\u0C80-\u0CFF]/ },
  { name: 'Malayalam', re: /[\u0D00-\u0D7F]/ },
  { name: 'Urdu/Arabic', re: /[\u0600-\u06FF]/ }
];
const detectedScripts = SCRIPTS.filter(s => s.re.test(newMsgText)).map(s => s.name);
// Anything that is NOT Devanagari and NOT plain Roman = a language we must not reply in.
const foreignScripts = detectedScripts.filter(s => s !== 'Hindi (Devanagari)');
const scriptLabel = detectedScripts.length ? detectedScripts.join(', ') : 'Roman/Latin letters';

// ---- CUSTOMER / ORDER CONTEXT (qrCustomerContext -> Shopify) ----
// The node is set to continue on error and always output data, so a Shopify outage or a
// missing token degrades to "no data" and the bot says the team will check - it must never
// block the reply.
let orderSummary = '';
let orderCtxDebug = 'node missing';
try {
  const cx = $('Fetch Customer Context').first().json || {};
  if (cx.error) orderCtxDebug = 'error: ' + cx.error;
  else if (cx.found && cx.summary) { orderSummary = String(cx.summary); orderCtxDebug = cx.orderCount + ' orders (' + (cx.source || '?') + ')'; }
  else orderCtxDebug = 'no orders found (' + (cx.source || '?') + ')';
} catch (e) { orderCtxDebug = 'node missing'; }

// ---- LIVE PRODUCT / PRICE MATCHES (qrProductLookup -> Shopify catalog) ----
let productSummary = '';
let productCtxDebug = 'node missing';
try {
  const px = $('Fetch Product Matches').first().json || {};
  if (px.error) productCtxDebug = 'error: ' + px.error;
  else if (px.found && px.summary) { productSummary = String(px.summary); productCtxDebug = px.matches.length + ' match(es) of ' + px.catalogSize + ' (' + (px.source || '?') + ')'; }
  else productCtxDebug = 'no match of ' + (px.catalogSize || 0) + ' (' + (px.source || '?') + ')';
} catch (e) { productCtxDebug = 'node missing'; }

const conversationContext = recentHistory.map(h => h.content).join(' ').toLowerCase();
const hasGreetingInHistory = conversationContext.includes('main ananya hoon') || conversationContext.includes('health expert at sehatup');

let systemPrompt = basePrompt
  + '\n\nCONTEXT:\nFirst contact: ' + (isFirstContact ? 'YES' : 'NO')
  + '\nCurrent time (customer message, IST): ' + clock + ' (' + partOfDay + ')'
  + '\nOffice hours: ' + (isOfficeHours ? 'OPEN' : 'CLOSED')
  + '\nTime since customer\'s previous message: ' + gapLabel
  + '\nCustomer name: ' + name
  + '\nCustomer wrote in: ' + scriptLabel
  + '\nGreeting already sent: ' + (hasGreetingInHistory ? 'YES' : 'NO')
  + '\n\nCRITICAL ANTI-SPAM RULES:\n'
  + '1. If "Greeting already sent: YES", NEVER send greeting again. Jump straight to answering the question.\n'
  + '2. If conversation history shows you already introduced yourself as Ananya, do NOT repeat introduction.\n'
  + '3. Only greet if: First contact: YES AND Greeting already sent: NO AND no assistant messages in history.\n'
  + '4. For follow-up questions, respond directly without any greeting or introduction.'
  + '\n5. Agar aapne pichle assistant message mein already free consultation/doctor-pitch wala paragraph bheja hai, to usko word-for-word ya near-identical dobara mat bhejo - short naya angle do ya seedha agla step (jaise time confirm karna) pucho.';

systemPrompt += '\n\nADDRESS POLICY (hard rule): the customer\'s gender is UNKNOWN. NEVER write sir, mam, ma\'am, madam, mem, ji sir, ji mam, bhai, bhaiya, bro, brother, behen, didi or bhabhi - not even if the customer calls themselves that, and not even once. Address them only as "ji", "aap", or their first name.';

systemPrompt += '\n\nLANGUAGE POLICY (hard rule - overrides any "match the customer\'s language" line above):'
  + '\n1. You reply ONLY in Hindi, English, or Hinglish (Hindi written in Roman letters). Nothing else. Default is simple Hinglish in Roman letters.'
  + '\n2. Customer writes Hinglish -> reply Hinglish. Customer writes English -> reply English. Customer writes Hindi in Devanagari -> reply in Hindi or Hinglish.'
  + '\n3. Customer writes in ANY other language or script (Tamil, Telugu, Kannada, Malayalam, Bengali, Marathi, Gujarati, Punjabi, Odia, Assamese, Urdu, Arabic, Nepali, Bhojpuri, or any foreign language) -> understand it fully, but STILL answer only in simple Hinglish or English. Use short easy words so they can follow.'
  + '\n4. Never type in that other script, never mix its words into your reply, never say sorry for the language and never say you cannot speak it. Just answer the question normally.';

if (foreignScripts.length) {
  systemPrompt += '\n\nLANGUAGE NOTE: this customer typed in ' + foreignScripts.join(', ') + '. Reply ONLY in simple Hinglish (Roman letters) - do not use that script anywhere in your reply.';
}

systemPrompt += '\n\nDOSAGE POLICY (hard rule):'
  + '\n1. You NEVER give the dose, quantity, timing or duration of anything - tablet, capsule, powder, drops, tea, kit or home remedy. Not a "general" dose, not a "normal" one, not even if the customer insists, has already bought it, or says a doctor told them.'
  + '\n2. If the customer asks kitni goli / kitni matra / khurak / dose / kaise leni hai / kab leni hai / kitne din leni hai / khali pet ya khane ke baad / how many / how much / how to take - do NOT answer and do NOT guess. Reply in this spirit, 1-2 short lines: "Dose doctor hi batate hain ji. Hamari team aapse thodi hi der me connect kar rahi hai, please thoda wait kijiye."'
  + '\n3. You may still tell them what the product helps with and its catalog price. Only the dose, timing and duration are off limits.';

// ---- PRODUCT POLICY ----
// The Google Doc still carries a CATALOG block with hand-typed prices. It goes stale the
// moment anything changes in Shopify, so where the two disagree the live data must win -
// stated explicitly, because the model will otherwise happily quote the prompt's number.
if (productSummary) {
  systemPrompt += '\n\nLIVE PRODUCT DATA (from Shopify right now):\n' + productSummary;
  systemPrompt += '\n\nPRODUCT POLICY (hard rule, OVERRIDES the CATALOG list above):'
    + '\n1. For any product named in LIVE PRODUCT DATA, the price, stock and link there are the ONLY correct ones. If the CATALOG block above shows a different price, the CATALOG is out of date - use the live price and never mention the difference.'
    + '\n2. Never quote a price for a product that is not in LIVE PRODUCT DATA. Say the team will confirm the exact price.'
    + '\n3. A product marked PRESCRIPTION ONLY: never share its link or price. Say it needs a doctor\'s prescription and offer the free consultation (for performance you may offer Vaji Bati instead, if it appears above).'
    + '\n4. A product marked OUT OF STOCK: do not push it or send its link. Offer the free consultation so the team can suggest an alternative.'
    + '\n5. Share at most 2 products, the most relevant one first. Never dump the list.'
    + '\n6. Use the exact product name shown above, and paste the link as a plain URL.'
    + '\n7. An "about:" line is what that product is for. Use it to explain the product in your own short simple Hinglish - 1-2 lines, never a paragraph, never copy it word for word, never read it out like a webpage.'
    + '\n8. The "about:" text is the ONLY product information you have. Do not add benefits, ingredients, results or timelines that are not in it. If they ask something it does not answer (how it works, ingredients, side effects, how long till results), say the doctor will explain properly in the free consultation.'
    + '\n9. Never state a dose, quantity, timing or duration even if you think you know it - that stays with the doctor (see DOSAGE POLICY).';
} else {
  systemPrompt += '\n\nPRODUCT POLICY (hard rule): no live product match was found for this message.'
