    // "Decide Process" tell the AI's own replies apart from a human takeover.
    senderKind: 'AI',
    messageBy: 'AI',
    _type: 'AGENT_TEXT',
    text: ai.lastAiReply,
    status: 'SENT',
    msgTime: now,
    createdAt: new Date().toISOString()
  }
}];

