const b = ($('QuickReply Webhook').first().json.body) || {};
const isStatus = !(b.payload && b.payload._type);
try {
  $execution.customData.set('kind', isStatus ? 'STATUS' : 'MESSAGE');
  $execution.customData.set('phone', String(b.phone || ''));
  if (isStatus) {
    $execution.customData.set('event', String(b.event || ''));
    $execution.customData.set('by', String(b.messageBy || ''));
  } else {
    $execution.customData.set('text', String((b.payload && b.payload.text) || '').slice(0, 60));
  }
} catch (e) { /* customData unavailable on this plan — ignore */ }
return $input.all();

